// E2E checks for issue #9 (C1/C2/C3): the radius slider / semantic zoom over
// graph.html opened as file://. Drives the real embedded JS with Playwright/Chromium.
//
// Prereq: graph.html is generated by the exact binary via `make run`, not hand-made.

import { chromium } from 'playwright';
import { execFileSync } from 'node:child_process';
import { rmSync } from 'node:fs';
import { resolve } from 'node:path';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';

const REPO = resolve(import.meta.dirname, '..', '..');
const IMAGE = process.env.IMAGE || 'class-viewer-dev:issue-9';

function generate(fixture, rel) {
    const out = resolve(REPO, rel);
    execFileSync('make', ['run', `IMAGE=${IMAGE}`,
        `ARGS=tests/fixtures/graph/${fixture} --output ${rel}`],
        { cwd: REPO, stdio: 'pipe' });
    return { out, url: pathToFileURL(out).href };
}

// Text of the detailed focus node (FQCN + namespace).
function focusText(page) {
    return page.$eval('g.node circle[r="10"]', (c) => c.parentElement.querySelector('text').textContent);
}
// Short names of the clickable distance-1 neighbours, sorted.
function neighbourNames(page) {
    return page.$$eval('g.node circle[r="6"]', (cs) =>
        cs.map((c) => c.parentElement.querySelector('text').textContent).sort());
}
// Count of dim distance-2+ points (class "far", no label).
function farCount(page) {
    return page.$$eval('g.node.far', (gs) => gs.length);
}
// Set the radius slider and let the input handler redraw.
async function setRadius(page, value) {
    await page.$eval('#radius', (el, v) => {
        el.value = String(v);
        el.dispatchEvent(new Event('input', { bubbles: true }));
    }, value);
}
// Re-centre by clicking the given node id.
async function clickNode(page, id) {
    await page.click(`g.node[data-id="${id.replace(/\\/g, '\\\\')}"]`);
}

async function egoChecks(page) {
    await clickNode(page, 'App\\Consumer');
    await page.waitForFunction(() =>
        document.querySelector('g.node circle[r="10"]')
            ?.parentElement.querySelector('text').textContent === 'App\\Consumer (App)');

    // --- C1.1: default radius is 1; Consumer shows only its direct neighbour Focus, no far point.
    assert.equal(await page.$eval('#radius', (el) => el.value), '1', 'C1.1: default radius is 1');
    assert.deepEqual(await neighbourNames(page), ['Focus'], 'C1.1: R=1 shows only Focus');
    assert.equal(await farCount(page), 0, 'C1.1: R=1 has no far point');

    // --- C1.2 / C2.1: at R=2, Dep appears as a dim far point (no label), Focus stays a named neighbour.
    await setRadius(page, 2);
    assert.deepEqual(await neighbourNames(page), ['Focus'], 'C1.2: Focus stays the named neighbour');
    assert.equal(await farCount(page), 1, 'C1.2: Dep is the single far point');
    const dep = await page.$('g.node.far[data-id="App\\\\Dep"]');
    assert.ok(dep, 'C2.1: the far point is App\\Dep');
    assert.equal(await dep.$('text'), null, 'C2.1: far point has no label');

    // --- C2.2: clicking the far point does not re-centre.
    await clickNode(page, 'App\\Dep');
    assert.equal(await focusText(page), 'App\\Consumer (App)', 'C2.2: far point is not clickable');

    // --- C1.3: back to R=1, Dep disappears.
    await setRadius(page, 1);
    assert.equal(await farCount(page), 0, 'C1.3: tightening removes the far point');
}

async function deepPerfCheck(page) {
    await clickNode(page, 'App\\Focus');
    await page.waitForFunction(() =>
        document.querySelector('g.node circle[r="10"]')
            ?.parentElement.querySelector('text').textContent === 'App\\Focus (App)');

    // --- C3.1: radius max (3) over the dense `deep` fixture; measure the redraw and count far points.
    const elapsed = await page.evaluate(() => {
        const slider = document.getElementById('radius');
        slider.value = '3';
        const start = performance.now();
        slider.dispatchEvent(new Event('input', { bubbles: true }));
        return performance.now() - start;
    });
    assert.ok(elapsed < 1000, `C3.1: redraw at R=3 must be < 1000 ms, was ${elapsed.toFixed(1)} ms`);
    assert.ok(await farCount(page) >= 200, 'C3.1: >=200 distance-2 classes rendered as points');
}

async function run() {
    const browser = await chromium.launch();
    const artifacts = [];
    try {
        const page = await browser.newPage();
        const errors = [];
        page.on('pageerror', (e) => errors.push(String(e)));

        const ego = generate('ego', 'tests/e2e/.distance-ego.html');
        artifacts.push(ego.out);
        await page.goto(ego.url);
        await page.waitForSelector('g.node');
        await egoChecks(page);

        const deep = generate('deep', 'tests/e2e/.distance-deep.html');
        artifacts.push(deep.out);
        await page.goto(deep.url);
        await page.waitForSelector('g.node');
        await deepPerfCheck(page);

        assert.deepEqual(errors, [], 'no JS error anywhere during the run');
        console.log('OK: C1.1 C1.2 C1.3 C2.1 C2.2 C3.1');
    } finally {
        await browser.close();
        artifacts.forEach((f) => rmSync(f, { force: true }));
    }
}

run().catch((e) => { console.error(e); process.exit(1); });
